import{_ as t,a0 as l,w as d,s as o,ao as r,I as p,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用 du 檢查 Linux 上已用的磁盤空間 | LCTT x X-CMD","titleTemplate":false,"description":"使用 du 檢查 Linux 上已用的磁盤空間 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 du 檢查 Linux 上已用的磁盤空間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 du 檢查 Linux 上已用的磁盤空間 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210727 Check used disk space on Linux with du","title":"使用 du 檢查 Linux 上已用的磁盤空間","tag":"202108","desc":""},"relativePath":"202108/20210727 Check used disk space on Linux with du.md","filePath":"[post].md"}'),u={name:"202108/20210727 Check used disk space on Linux with du.md"};function h(c,s,k,g,b,m){const e=l("Link");return d(),o("div",null,[s[18]||(s[18]=r(`<h1 id="使用-du-檢查-linux-上已用的磁盤空間" tabindex="-1">使用 du 檢查 Linux 上已用的磁盤空間 <a class="header-anchor" href="#使用-du-檢查-linux-上已用的磁盤空間" aria-label="Permalink to “使用 du 檢查 Linux 上已用的磁盤空間”">​</a></h1><blockquote><p>用 Linux 的 du 命令瞭解你正在使用多少磁盤空間。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/06/200731j561cwxyxyekaic5.jpg" alt=""></p><p>無論你有多少存儲空間，它總有可能被填滿。在大多數個人設備上，磁盤被照片、視頻和音樂填滿，但在服務器上，由於用户賬户和日誌文件數據，空間減少是很正常的。無論你是負責管理一個多用户系統，還是隻負責自己的筆記本電腦，你都可以用 <code>du</code> 命令檢查磁盤的使用情況。</p><p>默認情況下，<code>du</code> 列出了當前目錄中使用的磁盤空間，以及每個子目錄的大小。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du</span></span>
<span class="line"><span>12 ./.backups</span></span>
<span class="line"><span>60 .</span></span></code></pre></div><p>在這個例子中，當前目錄總共佔用了 60KB，其中 12KB 被子目錄 <code>.backups</code> 佔用。</p><p>如果你覺得這很混亂，並希望分別看到所有的大小，你可以使用 <code>--separate-dirs</code>（或簡寫 <code>-S</code>）選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du --separate-dirs</span></span>
<span class="line"><span>12 ./.backups</span></span>
<span class="line"><span>48 .</span></span></code></pre></div><p>顯示相同的信息（48KB 加 12KB 是 60KB），但每個目錄被獨立處理。</p><p>如需看到更多的細節，可以使用 <code>--all</code>（簡寫 <code>-a</code>）選項，它顯示每個目錄中以及每個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du --separate-dirs --all        </span></span>
<span class="line"><span>4    ./example.adoc</span></span>
<span class="line"><span>28   ./graphic.png</span></span>
<span class="line"><span>4    ./.backups/example.adoc~</span></span>
<span class="line"><span>12   ./.backups</span></span>
<span class="line"><span>4    ./index.html</span></span>
<span class="line"><span>4    ./index.adoc</span></span>
<span class="line"><span>48   .</span></span></code></pre></div><h3 id="查看文件的修改時間" tabindex="-1">查看文件的修改時間 <a class="header-anchor" href="#查看文件的修改時間" aria-label="Permalink to “查看文件的修改時間”">​</a></h3><p>當查看文件以找出佔用空間的內容時，查看文件最後一次被修改的時間是很有用的。一年內沒有使用過的文件可以考慮歸檔，特別是當你的空間快用完時。</p><p>通過 <code>du</code> 查看文件的修改時間，使用 <code>--time</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du --separate-dirs --all --time</span></span>
<span class="line"><span>28   2021-07-21 11:12    ./graphic.png</span></span>
<span class="line"><span>4    2021-07-03 10:43    ./example.adoc</span></span>
<span class="line"><span>4    2021-07-13 13:03    ./index.html</span></span>
<span class="line"><span>4    2021-07-23 14:18    ./index.adoc</span></span>
<span class="line"><span>48   2021-07-23 14:19    .</span></span></code></pre></div><h3 id="為文件大小設置一個閾值" tabindex="-1">為文件大小設置一個閾值 <a class="header-anchor" href="#為文件大小設置一個閾值" aria-label="Permalink to “為文件大小設置一個閾值”">​</a></h3><p>當為了磁盤空間而查看文件時，你可能只關心較大的文件。你可以通過 <code>--threshold</code>（簡寫 <code>-t</code>）選項為文件大小設置一個閾值。例如，只查看大於 1GB 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ \\du --separate-dirs --all --time --threshold=1G ~/Footage/</span></span>
<span class="line"><span>1839008 2021-07-14 13:55    /home/tux/Footage/snowfall.mp4</span></span>
<span class="line"><span>1577980 2020-04-11 13:10    /home/tux/Footage/waterfall.mp4</span></span>
<span class="line"><span>8588936 2021-07-14 13:55    /home/tux/Footage/</span></span></code></pre></div><p>當文件較大時，它們可能難以閲讀。使用 <code>--human-readable</code>（簡寫 <code>-h</code>）選項可以使文件大小更容易閲讀：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du --separate-dirs --all --time --threshold=1G --human-readable ~/Footage/</span></span>
<span class="line"><span>1.8G 2021-07-14 13:55    /home/tux/Footage/snowfall.mp4</span></span>
<span class="line"><span>1.6G 2020-04-11 13:10    /home/tux/Footage/waterfall.mp4</span></span>
<span class="line"><span>8.5G 2021-07-14 13:55    /home/tux/Footage/</span></span></code></pre></div><h3 id="查看可用磁盤空間" tabindex="-1">查看可用磁盤空間 <a class="header-anchor" href="#查看可用磁盤空間" aria-label="Permalink to “查看可用磁盤空間”">​</a></h3>`,22)),p("p",null,[s[1]||(s[1]=a("如需獲得一個驅動器上可用磁盤空間的摘要，請閲讀我們關於 ",-1)),n(e,{href:"https://opensource.com/article/21/7/use-df-check-free-disk-space-linux"},{default:i(()=>[...s[0]||(s[0]=[a("df 命令",-1)])]),_:1}),s[2]||(s[2]=a("的文章。",-1))]),s[19]||(s[19]=p("hr",null,null,-1)),p("p",null,[s[4]||(s[4]=a("via: ",-1)),n(e,{href:"https://opensource.com/article/21/7/check-disk-space-linux-du"},{default:i(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/21/7/check-disk-space-linux-du",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=a("作者：",-1)),n(e,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[5]||(s[5]=[a("Seth Kenlon",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[7]||(s[7]=[a("geekpi",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),n(e,{href:"https://github.com/turbokernel"},{default:i(()=>[...s[8]||(s[8]=[a("turbokernel",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const T=t(u,[["render",h]]);export{C as __pageData,T as default};
